#!/usr/bin/env python3
"""
Generate questions.json for all 61 LEGACY signs (E-series, B15A variants, F-series).
"""
import json, os

BASE = r"C:\Users\haydar\Desktop\end_project\readyroad\src\main\resources\data\signs_import"

def q3(qid, qtype, diff, crit, nl_q, nl_c, nl_e, en_q, en_c, en_e, fr_q, fr_c, fr_e, ar_q, ar_c, ar_e):
    def lang(q, c, e): return {"question": q, "choices": [{"text": t, "is_correct": ok} for t, ok in c], "explanation": e}
    return {"question_id": qid, "type": qtype, "difficulty": diff, "is_critical": crit, "show_sign": True,
            "i18n": {"NL": lang(nl_q,nl_c,nl_e), "EN": lang(en_q,en_c,en_e), "FR": lang(fr_q,fr_c,fr_e), "AR": lang(ar_q,ar_c,ar_e)}}

def write(code, qs):
    p = os.path.join(BASE, code, "questions.json")
    with open(p, "w", encoding="utf-8") as f: json.dump(qs, f, ensure_ascii=False, indent=2)
    print(f"  {code}: {len(qs)} q -> {os.path.getsize(p)} B")

