     [("لا: الحجز ينطبق دائماً؛ إشغال المواقف الأخرى لا يُغيّر القاعدة",Y),("نعم: القوة القاهرة تُتيح انحرافاً مؤقتاً عن حجوزات الوقوف",N),("نعم، لمدة أقصاها 30 دقيقة",N)],
